const item = $input.first().json;

// 解析技術棧
const stackRaw = item['語言、框架、驗證方式（如果選擇backend才需要選）'] || '';
const parts = stackRaw ? stackRaw.split(' + ') : ['', '', ''];

const language = parts[0].trim(); // TypeScript / .NET
const framework = parts[1].trim(); // NestJS / Express / Web API
const validation = parts[2].trim(); // Joi / Zod / class-validator / FluentValidation / DataAnnotations

const database = item['資料庫'];
const projectName = item['專案名稱'];
const projectDescription = item['專案描述'];
const generateType = item['產生類型'];
const projectPath = item['projectPath'];

// 判斷是否為 dotnet
const isDotnet = language === '.NET';

// 建立套件查詢清單
const packages = [];

if (!isDotnet) {
  // 固定套件
  packages.push('typescript');
  packages.push('helmet');
  packages.push('bcrypt');

  if (framework === 'NestJS') {
    packages.push('@nestjs/core');
    packages.push('@nestjs/common');
    packages.push('@nestjs/platform-express');
    packages.push('@nestjs/config');
    packages.push('@nestjs/jwt');
    packages.push('@nestjs/passport');
    packages.push('passport');
    packages.push('passport-jwt');
  } else if (framework === 'Express') {
    packages.push('express');
  }

  // 驗證套件
  if (validation === 'Joi') packages.push('joi');
  else if (validation === 'Zod') packages.push('zod');
  else if (validation === 'class-validator') {
    packages.push('class-validator');
    packages.push('class-transformer');
  }

  // 資料庫套件
  if (database === 'mongodb') packages.push('mongodb');
  else if (database === 'postgresql') packages.push('pg');
  else if (database === 'mysql') packages.push('mysql2');
  else if (database === 'mssql') packages.push('mssql');
} else {
  // .NET 套件
  packages.push('Microsoft.AspNetCore.OpenApi');
  packages.push('BCrypt.Net-Next');
  if (validation === 'FluentValidation') packages.push('FluentValidation.AspNetCore');
}

// 把 packages 陣列展開成多個 items，每個 item 就是一個套件名稱
return packages.map(pkg => ({
  json: {
    packageName: pkg,
    projectName,
    projectDescription,
    generateType,
    language,
    framework,
    validation,
    database,
    projectPath,
    isDotnet
  }
}));

const item = $input.first().json;
const { projectName, projectDescription, framework, validation, database, projectPath, generateType } = item;
const isTypespec = generateType === 'typespec' || generateType === 'both';
const isBackend = generateType === 'backend' || generateType === 'both' || !generateType;

const isMongo = database === 'mongodb';
const isJoi = validation === 'Joi';
const isZod = validation === 'Zod';
const isClassValidator = validation === 'class-validator';

// ─── dependencies ────────────────────────────────────────────────
const dependencies = {
  '@nestjs/common': 'latest',
