  '@nestjs/platform-express': 'latest',
  '@nestjs/config': 'latest',
  '@nestjs/jwt': 'latest',
  '@nestjs/passport': 'latest',
  'passport': 'latest',
  'passport-jwt': 'latest',
  'helmet': 'latest',
  'bcryptjs': 'latest',
  'reflect-metadata': 'latest',
  'rxjs': 'latest',
  'luxon': 'latest',
  'cookie-parser': 'latest',
  'moment': 'latest',
  'moment-timezone': 'latest',
  'body-parser': 'latest',
  '@nestjs/axios': 'latest',
  'axios': 'latest',
};

if (isJoi) dependencies['joi'] = 'latest';
if (isZod) dependencies['zod'] = 'latest';
if (isClassValidator) {
  dependencies['class-validator'] = 'latest';
  dependencies['class-transformer'] = 'latest';
}

if (isMongo) {
  dependencies['mongodb'] = 'latest';
} else {
  dependencies['nest-knexjs'] = 'latest';
  dependencies['knex'] = 'latest';
  if (database === 'postgresql') {
    dependencies['pg'] = 'latest';
  } else if (database === 'mysql') {
    dependencies['mysql2'] = 'latest';
  } else if (database === 'mssql') {
    dependencies['mssql'] = 'latest';
  }
}

