  const result = value.match(/[A-Z]/g)
  return result?.length ?? 0 > 0
}

export function hasLower(value: string) {
  const result = value.match(/[a-z]/g)
  return result?.length ?? 0 > 0
}

export function hasNumber(value: string) {
  const result = value.match(/[\\d]/g)
  return result?.length ?? 0 > 0
}

export function hasPunctuation(value: string) {
  const result = value.match(/[^\\w\\s]/g)
  return result?.length ?? 0 > 0
}

export function hasSpace(value: string) {
