  return result?.length ?? 0 > 0
}

export function isChinese(value: string) {
  for (const character of Array.from(value)) {
    if (['．'].includes(character)) continue
    if (character.length === 2) {
      if (!/^[\\uD800-\\uDBFF][\\uDC00-\\uDFFF]+$/.test(character)) return false
    } else {
      if (!/^[\\u4E00-\\u9FFF\\u3400-\\u4DBF\\uFA0E-\\uFA29\\uFA2E-\\uFA6D]+$/.test(character)) return false
    }
  }
  return true
}

export function isEnglish(value: string) {
