  const scale = upper - lower + 1
  return Math.floor(lower + Math.random() * scale)
}

export function getRandomNumbers(length: number) {
  return getRandomCharacters(length, '0123456789')
}

export function getRandomCode(length: number) {
  return getRandomCharacters(length, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789')
}

export function getRandomCharacters(length: number, characters: string) {
  let result = ''
  while (length > 0) {
    const index = Math.floor(Math.random() * characters.length)
    result += characters.charAt(index)
    length--
  }
  return result
}
`,
});

