  content: `import { Metadata, PagingQuery, SortColumn } from '../models/shared/pagination'

function _getSortColumns(sortQuerystring: string | undefined, defaultSort: SortColumn[]) {
  const arr = sortQuerystring ? sortQuerystring.split(',') : []
  if (arr.length === 0) return defaultSort
  const sortColumns: SortColumn[] = []
  for (let part of arr) {
    part = part.trim()
    if (!part) continue
    const isDesc = part.indexOf('-') === 0
    const name = part.replace(/[^0-9a-zA-Z._]/g, '')
    sortColumns.push({ column: name, order: isDesc ? 'desc' : 'asc' })
  }
  return sortColumns
}

export function getMetadata(
  count: number,
  paging: PagingQuery,
  defaultSort: SortColumn[] = [{ column: '_id', order: 'desc' }],
): Metadata {
  paging.limit = +paging.limit
  paging.page = +paging.page
  const sortColumns = _getSortColumns(paging.sort, defaultSort)
  const last = Math.floor(count / paging.limit) + (count % paging.limit > 0 ? 1 : 0)
  const pageExists = paging.page > 0 && paging.page <= last
  return {
    count,
    page: pageExists ? paging.page : 1,
    last: pageExists ? last : 1,
    limit: paging.limit,
    sort: sortColumns,
  }
}
`,
});

