import type { Request } from 'express'
import { DateTime } from 'luxon'
import { isDate, isNullOrUndefined, isString } from './util.helper'

export function getRefreshToken(req: Request, refreshCookieName: string): string | null {
  const signedCookies = req.signedCookies as Record<string, string> | undefined
  if (!signedCookies || !signedCookies[refreshCookieName]) return null
  const token = signedCookies[refreshCookieName]
  return typeof token === 'string' ? token : null
}

export function getUserId(req: Request): string {
  if (isNullOrUndefined(req.user)) throw new UnauthorizedException('missing req.user')
  const user = req.user as { _id: string }
  if (!user._id) throw new UnauthorizedException('missing user._id')
  return user._id
}

export function getUser<T>(req: Request): T {
  if (isNullOrUndefined(req.user)) throw new UnauthorizedException('missing req.user')
  return req.user as T
}

export function getFormattedString(pattern: string, values: Record<string, string>): string {
  let result = pattern
  for (const key of Object.keys(values)) {
    result = result.replace(new RegExp(\`{\${key}}\`), values[key])
  }
  return result
}

export function formatDateWithTimezone(date: Date | string, timezone: string): string {
