import type { ConfigService } from '@nestjs/config'
import * as bcrypt from 'bcryptjs'
import type { Response } from 'express'
import { hasLower, hasNumber, hasPunctuation, hasUpper } from './string.helper'
import { isNullOrEmpty } from './util.helper'

export function getHash(value: string): string {
  return bcrypt.hashSync(value)
}

export async function compareHash(value: string, hashedValue: string): Promise<boolean> {
  if (isNullOrEmpty(value) || isNullOrEmpty(hashedValue)) return false
  return bcrypt.compare(value, hashedValue)
}

export function validatePassword(
  username: string,
  password: string,
  confirmPassword: string,
  setting: { COMPLEXITY_CHECK_ENABLED?: boolean },
) {
  if (password !== confirmPassword) {
    throw new ForbiddenException('Confirm password is not matched')
  }
  if (username === password) {
    throw new ForbiddenException('The password cannot be the same as the username')
  }
  if (setting.COMPLEXITY_CHECK_ENABLED) {
    if (password.length < 8) {
      throw new ForbiddenException('Password must be at least 8 characters')
    }
    let formatCount = 0
    if (hasUpper(password)) formatCount++
    if (hasLower(password)) formatCount++
    if (hasNumber(password)) formatCount++
    if (hasPunctuation(password)) formatCount++
    if (formatCount < 3) {
      throw new ForbiddenException(
        'Password must contain at least 3 character types: uppercase, lowercase, numbers, and special characters.',
      )
    }
  }
}

export function getRefreshCookieName(configService: ConfigService): string {
  return configService.get<string>('REFRESH_COOKIE_NAME') || 'refresh_token'
}

export function setRefreshTokenCookie(
  res: Response,
  configService: ConfigService,
  refreshToken: string,
  maxAge: number,
): void {
  const name = getRefreshCookieName(configService)
  res.cookie(name, refreshToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    signed: true,
    maxAge,
  })
}

export function clearRefreshTokenCookie(res: Response, configService: ConfigService): void {
  const name = getRefreshCookieName(configService)
