import {
  Collection,
  Document,
  Filter,
  FindOptions,
  InsertOneResult,
  ObjectId,
  UpdateFilter,
  UpdateResult,
  DeleteResult,
  WithId,
} from 'mongodb'
import { DbClientService } from './db-client.service'

@Injectable()
export class DbQueryService {
  constructor(private dbClientService: DbClientService) {}

  private getCollection<T extends Document>(collectionName: string): Collection<T> {
    return this.dbClientService.getDb().collection<T>(collectionName)
  }

  async findOne<T extends Document>(
    collectionName: string,
    filter: Filter<T>,
    options?: FindOptions,
  ): Promise<WithId<T> | null> {
    return this.getCollection<T>(collectionName).findOne(filter, options)
  }

  async findMany<T extends Document>(
    collectionName: string,
    filter: Filter<T>,
    options?: FindOptions,
  ): Promise<WithId<T>[]> {
    return this.getCollection<T>(collectionName).find(filter, options).toArray()
  }

  async countDocuments<T extends Document>(
    collectionName: string,
    filter: Filter<T>,
  ): Promise<number> {
    return this.getCollection<T>(collectionName).countDocuments(filter)
  }

  async insertOne<T extends Document>(
    collectionName: string,
    doc: T,
  ): Promise<InsertOneResult<T>> {
    return this.getCollection<T>(collectionName).insertOne(doc as any)
  }

  async updateOne<T extends Document>(
    collectionName: string,
    filter: Filter<T>,
    update: UpdateFilter<T>,
  ): Promise<UpdateResult> {
    return this.getCollection<T>(collectionName).updateOne(filter, update)
  }

  async updateMany<T extends Document>(
    collectionName: string,
    filter: Filter<T>,
    update: UpdateFilter<T>,
  ): Promise<UpdateResult> {
    return this.getCollection<T>(collectionName).updateMany(filter, update)
  }

  async deleteOne<T extends Document>(
    collectionName: string,
    filter: Filter<T>,
  ): Promise<DeleteResult> {
    return this.getCollection<T>(collectionName).deleteOne(filter)
  }

  async findById<T extends Document>(
    collectionName: string,
    id: string | ObjectId,
  ): Promise<WithId<T> | null> {
    const _id = typeof id === 'string' ? new ObjectId(id) : id
    return this.getCollection<T>(collectionName).findOne({ _id } as Filter<T>)
  }

  async findWithPaging<T extends Document>(
    collectionName: string,
    filter: Filter<T>,
    page: number,
    limit: number,
    sort?: Record<string, 1 | -1>,
  ): Promise<{ data: WithId<T>[]; count: number }> {
    const skip = (page - 1) * limit
    const collection = this.getCollection<T>(collectionName)
    const [data, count] = await Promise.all([
      collection
        .find(filter)
        .sort(sort || { _id: -1 })
        .skip(skip)
        .limit(limit)
        .toArray(),
      collection.countDocuments(filter),
    ])
    return { data, count }
  }
}
`,
