  content: `import { Injectable, UnauthorizedException } from '@nestjs/common'
import { JwtService } from '@nestjs/jwt'
import { ConfigService } from '@nestjs/config'
import type { Response } from 'express'
import { UsersService } from '../users/users.service'
import { compareHash, getHash, setRefreshTokenCookie, clearRefreshTokenCookie } from '../../helpers/auth.helper'

@Injectable()
export class AuthService {
  constructor(
    private usersService: UsersService,
    private jwtService: JwtService,
    private configService: ConfigService,
  ) {}

  async login(email: string, password: string, res: Response) {
    const user = await this.usersService.findByEmail(email)
    if (!user) throw new UnauthorizedException('Invalid credentials')

    const isValid = await compareHash(password, user.password)
    if (!isValid) throw new UnauthorizedException('Invalid credentials')

    const payload = { sub: (user as any)._id?.toString() || (user as any).id, email: user.email }
    const accessToken = this.jwtService.sign(payload)
    const refreshToken = this.jwtService.sign(payload, {
      expiresIn: this.configService.get('REFRESH_TOKEN_EXPIRES_IN', '30d'),
    })

    const maxAge = 30 * 24 * 60 * 60 * 1000 // 30 days
    setRefreshTokenCookie(res, this.configService, refreshToken, maxAge)

    return { data: { accessToken, user: { _id: payload.sub, email: user.email } } }
  }

  async register(body: { email: string; password: string; name: string }) {
    const hashed = getHash(body.password)
    return this.usersService.create({ ...body, password: hashed })
  }

  logout(res: Response) {
    clearRefreshTokenCookie(res, this.configService)
    return { data: null }
  }
}
`,
});

