import { toObjectId } from '../../helpers/id-query.helper'
import { toResponse } from '../../models/shared/base'
import type { User } from '../../models/entities/user'

@Injectable()
export class UsersService {
  constructor(private dbQueryService: DbQueryService) {}

  async findByEmail(email: string) {
    return this.dbQueryService.findOne<User>(DocName.User, { email })
  }

  async findById(id: string) {
    const user = await this.dbQueryService.findOne<User>(DocName.User, {
      _id: toObjectId(id),
    })
    if (!user) throw new NotFoundException('User not found')
    const { password, ...rest } = toResponse(user) as any
    return { data: rest }
  }

  async create(data: Partial<User>) {
    const now = new Date()
    const user = { ...data, createdAt: now, updatedAt: now }
    await this.dbQueryService.insertOne<User>(DocName.User, user as User)
    return { data: { email: data.email, name: data.name } }
  }
}
` : `import { Injectable, NotFoundException } from '@nestjs/common'
